-- Adds 15 more placeholder success stories (same length as the tripled
-- quotes from 0011), so /stories has enough content for a proper grid.

insert into public.success_stories (name, title, title_de, title_fr, quote, quote_de, quote_fr, course_type_id, display_order)
values
  (
    'Nina R.',
    'Finally sitting up straight without thinking about it',
    'Endlich aufrecht sitzen, ohne daran zu denken',
    'Enfin assise droite sans y penser',
    'I spent a decade hunched over a laptop and figured stiff shoulders were just part of adult life. A colleague dragged me to a Saturday Mat class and I almost didn''t go back — my body ached in places I didn''t know existed. I''m glad I stuck with it. Three months in, my physiotherapist actually asked what changed, because my posture had visibly improved without me trying. What I didn''t expect was how much calmer I feel afterward too; the hour genuinely resets my whole week, not just my back.',
    'Ich habe ein Jahrzehnt gekrümmt vor dem Laptop verbracht und dachte, steife Schultern gehören einfach zum Erwachsenenleben. Eine Kollegin hat mich zu einem Samstags-Mat-Kurs mitgeschleppt, und ich wäre fast nicht wiedergekommen — mein Körper tat an Stellen weh, von denen ich nicht wusste, dass es sie gibt. Zum Glück bin ich drangeblieben. Nach drei Monaten hat mich meine Physiotherapeutin gefragt, was sich verändert hat, weil sich meine Haltung sichtbar verbessert hatte, ohne dass ich es bewusst versucht habe. Was ich nicht erwartet hatte: wie viel ruhiger ich mich danach fühle — die Stunde setzt wirklich meine ganze Woche zurück, nicht nur meinen Rücken.',
    'J''ai passé dix ans voûtée devant mon ordinateur et je pensais que des épaules raides faisaient simplement partie de la vie d''adulte. Une collègue m''a traînée à un cours de Mat le samedi, et j''ai failli ne pas y retourner — mon corps me faisait mal à des endroits dont j''ignorais l''existence. Heureusement, j''ai persévéré. Trois mois plus tard, ma physiothérapeute m''a demandé ce qui avait changé, car ma posture s''était visiblement améliorée sans que j''y travaille consciemment. Ce que je n''avais pas prévu, c''est à quel point je me sens plus calme après — l''heure remet vraiment toute ma semaine à zéro, pas seulement mon dos.',
    (select id from public.course_types where slug = 'mat-pilates'),
    4
  ),
  (
    'Daniel P.',
    'The class I was sure wasn''t for me',
    'Der Kurs, von dem ich sicher war, dass er nichts für mich ist',
    'Le cours dont j''étais sûr qu''il n''était pas pour moi',
    'I''ll admit it — I walked in assuming Pilates was too gentle to be worth my time, since I was already lifting weights three times a week. Within the first class I realized how wrong I was; muscles I thought were strong were shaking by the halfway point. It turned out to be exactly the missing piece in my training, filling in the stability and control that heavy lifting alone never built. My lower back pain from years of deadlifting has quietly disappeared, and my form in the gym has genuinely improved because of it.',
    'Ich gebe es zu — ich bin reingegangen und dachte, Pilates sei zu sanft, um meine Zeit wert zu sein, schliesslich habe ich schon dreimal die Woche Gewichte gestemmt. Schon in der ersten Stunde habe ich gemerkt, wie falsch ich lag; Muskeln, die ich für stark hielt, haben nach der Hälfte gezittert. Es stellte sich als genau das fehlende Puzzleteil in meinem Training heraus — die Stabilität und Kontrolle, die reines Krafttraining nie aufgebaut hat. Meine Rückenschmerzen von jahrelangem Kreuzheben sind still und leise verschwunden, und meine Form im Gym hat sich dadurch wirklich verbessert.',
    'Je l''avoue — j''y suis allé en pensant que le Pilates était trop doux pour valoir mon temps, puisque je soulevais déjà des poids trois fois par semaine. Dès le premier cours, j''ai réalisé à quel point je me trompais ; des muscles que je croyais forts tremblaient à mi-parcours. C''est devenu exactement la pièce manquante de mon entraînement, apportant la stabilité et le contrôle que la musculation seule n''a jamais construits. Mes douleurs lombaires dues à des années de soulevé de terre ont discrètement disparu, et ma technique en salle s''est vraiment améliorée grâce à ça.',
    (select id from public.course_types where slug = 'mat-pilates'),
    5
  ),
  (
    'Chiara V.',
    'The hour my brain finally stops',
    'Die Stunde, in der mein Kopf endlich abschaltet',
    'L''heure où mon cerveau s''arrête enfin',
    'Between two jobs and a toddler, my brain never really switches off, even in the evenings when I''m supposedly relaxing. I started Mat Pilates purely for the movement, but the real surprise was mental — the classes force you to focus so completely on breath and control that there''s simply no room left to worry about anything else. I leave every session with a clearer head than I''ve had in years, and my husband has actually noticed I''m less snappy on the days I go. My body feels better too, but honestly the calm is what keeps me coming back.',
    'Zwischen zwei Jobs und einem Kleinkind schaltet mein Kopf eigentlich nie richtig ab, selbst abends, wenn ich angeblich entspanne. Ich habe mit Mat Pilates nur wegen der Bewegung angefangen, aber die eigentliche Überraschung war mental — die Stunden zwingen einen, sich so komplett auf Atmung und Kontrolle zu konzentrieren, dass einfach kein Platz bleibt, sich um irgendetwas anderes zu sorgen. Ich verlasse jede Stunde mit einem klareren Kopf, als ich ihn seit Jahren hatte, und mein Mann hat tatsächlich bemerkt, dass ich an den Tagen, an denen ich hingehe, weniger schnippisch bin. Mein Körper fühlt sich auch besser an, aber ehrlich gesagt ist es die Ruhe, die mich zurückkommen lässt.',
    'Entre deux emplois et un enfant en bas âge, mon cerveau ne s''éteint jamais vraiment, même le soir quand je suis censée me détendre. J''ai commencé le Mat Pilates uniquement pour le mouvement, mais la vraie surprise a été mentale — les cours obligent à se concentrer si complètement sur la respiration et le contrôle qu''il ne reste tout simplement plus de place pour s''inquiéter d''autre chose. Je repars de chaque séance avec l''esprit plus clair que je ne l''ai eu depuis des années, et mon mari a même remarqué que je suis moins à cran les jours où j''y vais. Mon corps se sent mieux aussi, mais honnêtement, c''est le calme qui me fait revenir.',
    (select id from public.course_types where slug = 'mat-pilates'),
    6
  ),
  (
    'Tom H.',
    'Out of my desk-job slump, finally',
    'Endlich raus aus dem Schreibtisch-Tief',
    'Enfin sorti de ma torpeur de bureau',
    'Five years behind a desk had left me stiff in ways I didn''t even notice until I tried to touch my toes and couldn''t get anywhere close. I joined more out of embarrassment than ambition, expecting to be the worst person in the room. Nobody made me feel that way — the instructor adjusted everything to where I actually was, not where a fitter person would be. Six weeks in, I can touch my toes again, my hips don''t ache after long drives anymore, and I''ve stopped dreading the idea of exercise altogether, which honestly surprised me the most.',
    'Fünf Jahre hinter dem Schreibtisch hatten mich auf eine Weise steif gemacht, die ich gar nicht bemerkt hatte, bis ich versuchte, meine Zehen zu berühren, und nicht mal in die Nähe kam. Ich bin eher aus Verlegenheit als aus Ehrgeiz eingestiegen und habe erwartet, der Schlechteste im Raum zu sein. Niemand hat mich das spüren lassen — die Instruktorin hat alles an den Punkt angepasst, an dem ich tatsächlich war, nicht an dem, wo eine fittere Person wäre. Nach sechs Wochen kann ich meine Zehen wieder berühren, meine Hüften schmerzen nach langen Autofahrten nicht mehr, und ich fürchte den Gedanken an Sport überhaupt nicht mehr — das hat mich ehrlich am meisten überrascht.',
    'Cinq ans derrière un bureau m''avaient raidi d''une façon que je n''avais même pas remarquée, jusqu''à ce que j''essaie de toucher mes orteils sans même en approcher. Je me suis inscrit plus par gêne que par ambition, m''attendant à être le pire de la salle. Personne ne m''a fait ressentir ça — l''instructrice a tout adapté à là où j''en étais réellement, pas à là où serait une personne plus en forme. Six semaines plus tard, je touche à nouveau mes orteils, mes hanches ne me font plus mal après de longs trajets en voiture, et j''ai cessé de redouter l''idée même de faire du sport — ce qui m''a honnêtement le plus surpris.',
    (select id from public.course_types where slug = 'mat-pilates'),
    7
  ),
  (
    'Elena S.',
    'My running finally stopped falling apart at mile eight',
    'Mein Lauf bricht endlich nicht mehr bei Kilometer dreizehn ein',
    'Ma course ne s''effondre plus au treizième kilomètre',
    'As a runner, I always hit the same wall around mile eight, and my physio kept saying it was a strength issue, not a fitness one. I added Reformer sessions twice a week mostly out of desperation, without much hope it would change anything. Within two months, the wall had moved from mile eight to somewhere well past ten, and my times on hills improved without me running any more than before. The instructor understood exactly which muscles a runner needs and never made the session feel generic. It''s now a permanent part of my training, not a side experiment.',
    'Als Läuferin bin ich immer an der gleichen Wand bei Kilometer dreizehn hängengeblieben, und meine Physiotherapeutin meinte immer wieder, es sei ein Kraft-, kein Kondition-Problem. Ich habe aus purer Verzweiflung zweimal die Woche Reformer-Stunden dazugenommen, ohne grosse Hoffnung, dass sich etwas ändert. Innerhalb von zwei Monaten hatte sich die Wand von Kilometer dreizehn auf weit über sechzehn verschoben, und meine Zeiten an Steigungen haben sich verbessert, ohne dass ich mehr gelaufen bin als vorher. Die Instruktorin wusste genau, welche Muskeln eine Läuferin braucht, und die Stunde hat sich nie generisch angefühlt. Es ist jetzt fester Bestandteil meines Trainings, kein Nebenexperiment mehr.',
    'En tant que coureuse, je butais toujours sur le même mur vers le treizième kilomètre, et ma physiothérapeute répétait que c''était un problème de force, pas de forme. J''ai ajouté des séances de Reformer deux fois par semaine, surtout par désespoir, sans grand espoir que ça change quoi que ce soit. En deux mois, le mur s''était déplacé du treizième kilomètre à bien au-delà du seizième, et mes temps en côte se sont améliorés sans que je coure davantage qu''avant. L''instructrice savait exactement quels muscles une coureuse doit travailler, et la séance n''a jamais semblé générique. C''est maintenant une part permanente de mon entraînement, plus une simple expérience à côté.',
    (select id from public.course_types where slug = 'reformer-basics'),
    8
  ),
  (
    'Marco T.',
    'Back on the machine two years after knee surgery',
    'Zwei Jahre nach der Knie-OP wieder am Gerät',
    'De retour sur la machine deux ans après mon opération du genou',
    'Two years after knee surgery, I still babied that leg without even realizing it, favoring the other side in ways that were starting to cause new problems. My surgeon suggested Reformer work specifically because the machine supports controlled, low-impact movement instead of the harsh loading of a normal gym. The instructor tracked exactly how my knee moved every session and adjusted resistance so I never overreached. A year later, I trust that leg again completely, and I''ve stopped unconsciously shifting my weight away from it — something even my physio noticed before I did.',
    'Zwei Jahre nach meiner Knieoperation habe ich das Bein immer noch geschont, ohne es überhaupt zu merken, und das andere so bevorzugt, dass es langsam neue Probleme verursachte. Mein Chirurg hat mir gezielt Reformer-Training vorgeschlagen, weil das Gerät kontrollierte, gelenkschonende Bewegung ermöglicht statt der harten Belastung eines normalen Fitnessstudios. Die Instruktorin hat in jeder Stunde genau verfolgt, wie sich mein Knie bewegt, und den Widerstand entsprechend angepasst, sodass ich mich nie überfordert habe. Ein Jahr später vertraue ich dem Bein wieder vollständig, und ich verlagere mein Gewicht nicht mehr unbewusst davon weg — das hat sogar meine Physiotherapeutin bemerkt, bevor ich es selbst tat.',
    'Deux ans après mon opération du genou, je ménageais encore cette jambe sans même m''en rendre compte, en favorisant l''autre côté d''une façon qui commençait à créer de nouveaux problèmes. Mon chirurgien m''a suggéré le Reformer justement parce que la machine permet un mouvement contrôlé et à faible impact, contrairement aux charges brutales d''une salle de sport classique. L''instructrice suivait exactement comment mon genou bougeait à chaque séance et ajustait la résistance pour que je n''en fasse jamais trop. Un an plus tard, je fais de nouveau entièrement confiance à cette jambe, et j''ai arrêté de reporter inconsciemment mon poids ailleurs — ma physiothérapeute l''a remarqué avant moi.',
    (select id from public.course_types where slug = 'reformer-basics'),
    9
  ),
  (
    'Priya N.',
    'I thought the machine looked terrifying — now I love it',
    'Ich fand das Gerät furchteinflössend — jetzt liebe ich es',
    'Je trouvais la machine terrifiante — maintenant je l''adore',
    'The Reformer machine looked genuinely terrifying to me from the doorway before my first class — all those springs and straps seemed built for people already strong, not total beginners like me. The instructor walked me through every strap and spring setting like it was the most normal thing in the world, and within ten minutes the fear was gone completely. Three months in, I can do moves I couldn''t have imagined attempting on day one, and I''ve become the person who recommends it to every hesitant friend, because I remember exactly how they feel standing at that door.',
    'Das Reformer-Gerät wirkte von der Tür aus vor meiner ersten Stunde wirklich furchteinflössend auf mich — all diese Federn und Riemen sahen aus, als wären sie für Leute gemacht, die schon stark sind, nicht für absolute Anfängerinnen wie mich. Die Instruktorin hat mir jede Riemen- und Federeinstellung erklärt, als wäre es das Normalste der Welt, und nach zehn Minuten war die Angst komplett verschwunden. Nach drei Monaten kann ich Übungen machen, die ich mir am ersten Tag nicht mal hätte vorstellen können, und ich bin die Person geworden, die es jeder zögernden Freundin empfiehlt, weil ich mich genau daran erinnere, wie sie sich an dieser Tür fühlen.',
    'La machine Reformer me semblait vraiment terrifiante depuis la porte avant mon premier cours — tous ces ressorts et ces sangles paraissaient conçus pour des gens déjà forts, pas pour une débutante totale comme moi. L''instructrice m''a expliqué chaque sangle et chaque réglage de ressort comme si c''était la chose la plus normale au monde, et en dix minutes la peur avait complètement disparu. Trois mois plus tard, je fais des mouvements que je n''aurais jamais imaginé tenter le premier jour, et je suis devenue la personne qui le recommande à chaque amie hésitante, parce que je me souviens exactement de ce qu''elles ressentent devant cette porte.',
    (select id from public.course_types where slug = 'reformer-basics'),
    10
  ),
  (
    'Julia W.',
    'Switched from ten years of gym memberships, no regrets',
    'Nach zehn Jahren Fitnessstudio umgestiegen, keine Reue',
    'Après dix ans de salle de sport, aucun regret',
    'After a decade of standard gym memberships that I mostly used for cardio machines and the occasional class, I switched almost entirely to Reformer sessions and haven''t looked back once. What sold me was how every single muscle gets addressed with real precision, not just the ones I already knew how to train. My shoulders, which have always been my weak point after an old injury, finally feel balanced and strong instead of just achy. I still keep my gym membership for running, but the Reformer is where the actual strength work happens now, and it shows in everything else I do.',
    'Nach einem Jahrzehnt klassischer Fitnessstudio-Mitgliedschaften, die ich hauptsächlich für Cardiogeräte und gelegentliche Kurse genutzt habe, bin ich fast vollständig auf Reformer-Stunden umgestiegen und habe es keine Sekunde bereut. Überzeugt hat mich, wie jeder einzelne Muskel mit echter Präzision angesprochen wird, nicht nur die, die ich schon zu trainieren wusste. Meine Schultern, seit einer alten Verletzung immer meine Schwachstelle, fühlen sich endlich ausgeglichen und stark an statt nur schmerzend. Meine Studio-Mitgliedschaft behalte ich fürs Laufen, aber die eigentliche Kraftarbeit passiert jetzt am Reformer, und das zeigt sich in allem anderen, was ich tue.',
    'Après une décennie d''abonnements classiques en salle, surtout utilisés pour le cardio et quelques cours occasionnels, je suis passée presque entièrement aux séances de Reformer et je ne le regrette pas une seconde. Ce qui m''a convaincue, c''est la précision avec laquelle chaque muscle est sollicité, pas seulement ceux que je savais déjà entraîner. Mes épaules, mon point faible depuis une vieille blessure, se sentent enfin équilibrées et fortes au lieu de simplement douloureuses. Je garde mon abonnement en salle pour la course, mais le vrai travail de force se fait maintenant au Reformer, et ça se voit dans tout ce que je fais.',
    (select id from public.course_types where slug = 'reformer-basics'),
    11
  ),
  (
    'Carla M.',
    'Second pregnancy, so much easier than the first',
    'Zweite Schwangerschaft, so viel leichter als die erste',
    'Deuxième grossesse, tellement plus facile que la première',
    'My first pregnancy left me with pelvic pain that lingered for months after birth, mostly because I had no idea what movement was actually safe and just stopped exercising altogether out of fear. This time I joined Prenatal Pilates from the second trimester, and the difference has been enormous. The instructor explains exactly what''s happening in your body at each stage and adjusts every single exercise accordingly, so I never once felt unsure whether something was okay to do. My hips feel stronger at eight months pregnant now than they did at three months last time, which still surprises me.',
    'Meine erste Schwangerschaft hat mir Beckenschmerzen beschert, die noch Monate nach der Geburt anhielten, hauptsächlich weil ich keine Ahnung hatte, welche Bewegung wirklich sicher war, und aus Angst einfach ganz aufgehört habe, Sport zu treiben. Diesmal bin ich ab dem zweiten Trimester zu Schwangerschafts-Pilates gegangen, und der Unterschied ist enorm. Die Instruktorin erklärt genau, was in jeder Phase im Körper passiert, und passt jede einzelne Übung entsprechend an, sodass ich mir nie unsicher war, ob etwas in Ordnung ist. Meine Hüften fühlen sich im achten Monat jetzt stärker an, als sie es im dritten Monat beim letzten Mal waren — das überrascht mich immer noch.',
    'Ma première grossesse m''a laissé des douleurs pelviennes qui ont persisté des mois après l''accouchement, surtout parce que je ne savais pas quels mouvements étaient réellement sûrs et que j''avais complètement arrêté le sport par peur. Cette fois, j''ai rejoint le Pilates Prénatal dès le deuxième trimestre, et la différence est énorme. L''instructrice explique exactement ce qui se passe dans le corps à chaque étape et ajuste chaque exercice en conséquence, donc je n''ai jamais douté qu''un mouvement était approprié. Mes hanches se sentent plus fortes à huit mois de grossesse maintenant qu''elles ne l''étaient à trois mois la dernière fois — ça me surprend encore.',
    (select id from public.course_types where slug = 'prenatal-pilates'),
    12
  ),
  (
    'Nadia K.',
    'Terrified of moving wrong, until this class',
    'Panische Angst vor falscher Bewegung — bis zu diesem Kurs',
    'Terrifiée à l''idée de mal bouger, jusqu''à ce cours',
    'As a first-time mom, I was genuinely terrified of exercising at all during pregnancy, convinced I would somehow do something wrong and hurt the baby. A friend who''d taken Prenatal Pilates before basically pushed me into trying one class, and the instructor spent the entire first session just explaining what was and wasn''t safe at my stage, which calmed me down more than anything a doctor had said. Now at six months, I move more confidently than I have in years, my back pain is manageable, and I actually look forward to the one hour a week that''s entirely about me and this baby.',
    'Als werdende Erstmama hatte ich wirklich Angst davor, während der Schwangerschaft überhaupt Sport zu treiben, überzeugt, dass ich irgendwie etwas falsch machen und dem Baby schaden würde. Eine Freundin, die schon Schwangerschafts-Pilates gemacht hatte, hat mich praktisch dazu gedrängt, eine Stunde auszuprobieren, und die Instruktorin hat die gesamte erste Stunde damit verbracht, genau zu erklären, was in meinem Stadium sicher ist und was nicht — das hat mich mehr beruhigt als alles, was ein Arzt gesagt hat. Jetzt, im sechsten Monat, bewege ich mich selbstbewusster als seit Jahren, meine Rückenschmerzen sind erträglich, und ich freue mich tatsächlich auf die eine Stunde pro Woche, die ganz mir und diesem Baby gehört.',
    'En tant que future maman pour la première fois, j''avais vraiment peur de faire du sport pendant la grossesse, convaincue que je ferais forcément quelque chose de mal et blesserais le bébé. Une amie qui avait déjà suivi le Pilates Prénatal m''a pratiquement poussée à essayer un cours, et l''instructrice a passé toute la première séance à expliquer précisément ce qui était sûr ou non à mon stade, ce qui m''a rassurée bien plus que tout ce qu''un médecin avait pu dire. Maintenant, à six mois, je bouge avec plus de confiance que depuis des années, mes douleurs de dos sont gérables, et j''attends vraiment cette heure par semaine qui n''appartient qu''à moi et à ce bébé.',
    (select id from public.course_types where slug = 'prenatal-pilates'),
    13
  ),
  (
    'Isabelle F.',
    'Rebuilding my body after birth, one honest step at a time',
    'Meinen Körper nach der Geburt ehrlich wieder aufbauen',
    'Reconstruire mon corps après l''accouchement, honnêtement',
    'After giving birth, I expected to bounce back within a few months, and when that didn''t happen I felt genuinely lost about where to even start again safely. I came back to Prenatal Pilates for the postpartum sessions specifically because the instructor already knew my whole pregnancy history and didn''t need me to explain anything. She rebuilt my core from literally nothing, checking for the ab separation that''s common after birth before adding any real load. Five months postpartum, I feel stronger than I did before I got pregnant, and for the first time I''m not comparing my body to some imaginary timeline.',
    'Nach der Geburt hatte ich erwartet, mich innerhalb weniger Monate zu erholen, und als das nicht passierte, fühlte ich mich wirklich verloren, wo ich überhaupt sicher wieder anfangen sollte. Ich bin gezielt für die Rückbildungsstunden zu Schwangerschafts-Pilates zurückgekehrt, weil die Instruktorin meine ganze Schwangerschaftsgeschichte schon kannte und ich nichts erklären musste. Sie hat meinen Rumpf buchstäblich von null wieder aufgebaut und zuerst auf die nach der Geburt häufige Rektusdiastase geprüft, bevor überhaupt echte Belastung dazukam. Fünf Monate nach der Geburt fühle ich mich stärker als vor der Schwangerschaft, und zum ersten Mal vergleiche ich meinen Körper nicht mit irgendeinem imaginären Zeitplan.',
    'Après l''accouchement, je m''attendais à récupérer en quelques mois, et quand ce ne fut pas le cas, je me suis sentie vraiment perdue sur par où recommencer en toute sécurité. Je suis revenue au Pilates Prénatal spécifiquement pour les séances postnatales, parce que l''instructrice connaissait déjà toute mon histoire de grossesse et n''avait besoin d''aucune explication. Elle a reconstruit mon centre du corps littéralement à partir de rien, en vérifiant d''abord la diastase abdominale fréquente après l''accouchement avant d''ajouter la moindre vraie charge. Cinq mois après la naissance, je me sens plus forte qu''avant ma grossesse, et pour la première fois, je ne compare plus mon corps à un calendrier imaginaire.',
    (select id from public.course_types where slug = 'prenatal-pilates'),
    14
  ),
  (
    'Rebecca L.',
    'Carrying twins, and finally feeling supported instead of scared',
    'Zwillinge erwartend, endlich unterstützt statt ängstlich',
    'Enceinte de jumeaux, enfin soutenue plutôt qu''effrayée',
    'Finding out I was expecting twins turned every pregnancy fear I had up to double, and most regular prenatal advice online felt like it wasn''t written for my situation at all. The instructor here had actually worked with a twin pregnancy before and adjusted the entire program around my faster-growing belly and the extra strain on my back. What could have been the hardest pregnancy of my life instead felt genuinely manageable, week after week. I''m now thirty-two weeks along, still moving comfortably, and I credit these sessions directly with how much less afraid I feel walking into the final stretch.',
    'Die Nachricht, Zwillinge zu erwarten, hat jede Schwangerschaftsangst, die ich hatte, verdoppelt, und die meisten üblichen Ratschläge zur Schwangerschaft im Internet fühlten sich an, als wären sie überhaupt nicht für meine Situation geschrieben. Die Instruktorin hier hatte tatsächlich schon mit einer Zwillingsschwangerschaft gearbeitet und das gesamte Programm auf meinen schneller wachsenden Bauch und die zusätzliche Belastung für meinen Rücken abgestimmt. Was die schwerste Schwangerschaft meines Lebens hätte werden können, fühlte sich stattdessen Woche für Woche wirklich machbar an. Ich bin jetzt in der zweiunddreissigsten Woche, bewege mich noch immer komfortabel, und diese Stunden sind der direkte Grund, warum ich so viel weniger Angst vor der Zielgeraden habe.',
    'Apprendre que j''attendais des jumeaux a doublé chacune de mes peurs liées à la grossesse, et la plupart des conseils prénataux habituels en ligne semblaient ne pas du tout être écrits pour ma situation. L''instructrice ici avait déjà accompagné une grossesse gémellaire et a adapté tout le programme à mon ventre qui grossissait plus vite et à la tension supplémentaire sur mon dos. Ce qui aurait pu être la grossesse la plus difficile de ma vie s''est révélé, semaine après semaine, vraiment gérable. J''en suis maintenant à trente-deux semaines, je bouge encore confortablement, et je dois directement à ces séances de ressentir beaucoup moins de peur en abordant la dernière ligne droite.',
    (select id from public.course_types where slug = 'prenatal-pilates'),
    15
  ),
  (
    'Markus B.',
    'Sixty-eight years old and finally out of chronic pain',
    'Achtundsechzig Jahre alt und endlich schmerzfrei',
    'Soixante-huit ans et enfin sans douleur chronique',
    'At sixty-eight, I''d more or less accepted that lower back pain was simply part of getting older, something to manage rather than fix. My daughter convinced me to try a private session, mostly because I refused to join a group class at my age and skill level. The one-on-one format turned out to be exactly right — the instructor built a program around my actual limitations instead of a generic one, and adjusted constantly as my body responded. A year later, I garden for hours without needing to stop, and my doctor has genuinely asked what I''ve changed, because the improvement shows up in how I walk.',
    'Mit achtundsechzig hatte ich mich mehr oder weniger damit abgefunden, dass Rückenschmerzen einfach zum Älterwerden gehören — etwas, das man verwaltet statt behebt. Meine Tochter hat mich überredet, eine Einzelstunde auszuprobieren, hauptsächlich weil ich mich in meinem Alter und Können geweigert habe, an einem Gruppenkurs teilzunehmen. Das Einzelformat erwies sich als genau richtig — die Instruktorin hat ein Programm um meine tatsächlichen Einschränkungen herum gebaut statt ein generisches, und es ständig angepasst, wie mein Körper reagiert hat. Ein Jahr später gärtnere ich stundenlang, ohne pausieren zu müssen, und mein Arzt hat mich ernsthaft gefragt, was sich verändert hat, weil sich die Verbesserung in meinem Gangbild zeigt.',
    'À soixante-huit ans, j''avais plus ou moins accepté que les douleurs lombaires faisaient simplement partie du vieillissement, quelque chose à gérer plutôt qu''à résoudre. Ma fille m''a convaincu d''essayer une séance privée, surtout parce que je refusais de rejoindre un cours collectif à mon âge et à mon niveau. Le format individuel s''est révélé exactement ce qu''il me fallait — l''instructrice a construit un programme autour de mes limites réelles plutôt qu''un programme générique, et l''a constamment ajusté selon la réaction de mon corps. Un an plus tard, je jardine pendant des heures sans avoir besoin de m''arrêter, et mon médecin m''a sincèrement demandé ce qui avait changé, car l''amélioration se voit dans ma façon de marcher.',
    (select id from public.course_types where slug = 'private-1-1'),
    16
  ),
  (
    'Sandra O.',
    'Trained one-on-one for my first triathlon, and it worked',
    'Einzeltraining für meinen ersten Triathlon — und es hat funktioniert',
    'Entraînement individuel pour mon premier triathlon, et ça a marché',
    'Training for my first triathlon at forty-three, I knew my weak link wasn''t cardio but core stability, especially on the bike where fatigue made my form fall apart in the last third of every ride. I booked private sessions specifically to target that, explaining my race schedule so the instructor could plan around my actual training load instead of working in isolation. The sessions were built entirely around triathlon-specific weaknesses, not a generic strength routine. I finished my race four weeks ago with the strongest final ten kilometers of any training ride I''d done, and I''m already booking sessions for the next one.',
    'Beim Training für meinen ersten Triathlon mit dreiundvierzig wusste ich, dass mein Schwachpunkt nicht die Kondition war, sondern die Rumpfstabilität, besonders auf dem Rad, wo Ermüdung im letzten Drittel jeder Fahrt meine Form zerfallen liess. Ich habe gezielt Einzelstunden gebucht und meinen Rennplan erklärt, damit die Instruktorin um meine tatsächliche Trainingslast herum planen konnte, statt isoliert zu arbeiten. Die Stunden waren komplett um triathlonspezifische Schwächen aufgebaut, keine generische Kraftroutine. Ich habe mein Rennen vor vier Wochen mit den stärksten letzten zehn Kilometern jeder Trainingsfahrt beendet, die ich je gemacht habe, und buche schon Stunden für das nächste Rennen.',
    'En m''entraînant pour mon premier triathlon à quarante-trois ans, je savais que mon point faible n''était pas le cardio mais la stabilité du centre du corps, surtout à vélo, où la fatigue faisait s''effondrer ma posture dans le dernier tiers de chaque sortie. J''ai réservé des séances privées spécifiquement pour travailler ça, en expliquant mon calendrier de course pour que l''instructrice puisse planifier autour de ma charge d''entraînement réelle plutôt que de travailler isolément. Les séances étaient entièrement construites autour des faiblesses spécifiques au triathlon, pas une routine de force générique. J''ai terminé ma course il y a quatre semaines avec les dix meilleurs derniers kilomètres de toutes mes sorties d''entraînement, et je réserve déjà des séances pour la prochaine.',
    (select id from public.course_types where slug = 'private-1-1'),
    17
  ),
  (
    'Peter G.',
    'Too intimidated for group classes, glad I found another way',
    'Zu eingeschüchtert für Gruppenkurse, froh, einen anderen Weg gefunden zu haben',
    'Trop intimidé pour les cours collectifs, content d''avoir trouvé une autre voie',
    'I''d wanted to try Pilates for years but kept talking myself out of group classes, convinced everyone else would already know what they were doing while I fumbled through every move. A private session felt like less pressure, so I finally booked one purely to test the waters without an audience. The instructor moved at exactly my pace, explained the reasoning behind each exercise instead of just demonstrating it, and never once made me feel behind. Six months later, I''ve actually joined a small group class too, something I never thought I''d be confident enough to do, and I owe that entirely to starting privately first.',
    'Ich wollte seit Jahren Pilates ausprobieren, habe mir Gruppenkurse aber immer wieder ausgeredet, überzeugt, dass alle anderen schon wüssten, was sie tun, während ich mich durch jede Übung stolpern würde. Eine Einzelstunde fühlte sich nach weniger Druck an, also habe ich endlich eine gebucht, rein um es ohne Publikum zu testen. Die Instruktorin ist genau in meinem Tempo geblieben, hat die Begründung hinter jeder Übung erklärt statt sie nur vorzuführen, und hat mich nie das Gefühl geben lassen, hinterherzuhinken. Sechs Monate später bin ich tatsächlich auch einem kleinen Gruppenkurs beigetreten, etwas, von dem ich nie dachte, dass ich mich dafür sicher genug fühlen würde, und das verdanke ich komplett dem privaten Einstieg zuerst.',
    'Je voulais essayer le Pilates depuis des années, mais je me décourageais toujours face aux cours collectifs, convaincu que tout le monde saurait déjà quoi faire pendant que je bafouillerais à chaque mouvement. Une séance privée semblait moins pressante, alors j''en ai enfin réservé une, uniquement pour tester sans public. L''instructrice est restée exactement à mon rythme, expliquant le raisonnement derrière chaque exercice au lieu de simplement le démontrer, et ne m''a jamais donné l''impression d''être à la traîne. Six mois plus tard, j''ai même rejoint un petit cours collectif, quelque chose dont je n''aurais jamais cru me sentir assez confiant pour faire, et je le dois entièrement au fait d''avoir commencé en privé d''abord.',
    (select id from public.course_types where slug = 'private-1-1'),
    18
  )
on conflict do nothing;
